CREATE OR REPLACE FUNCTION public.fiscal_salvar_entrada(p_nota uuid,p_dados jsonb,p_itens jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e uuid:=public.get_auth_user_estabelecimento_id(); u uuid:=public.get_current_usuario_id_safe(); n uuid:=p_nota; un uuid:=nullif(p_dados->>'unidade_id','')::uuid; f uuid:=nullif(p_dados->>'empresa_id','')::uuid; i jsonb; chave text:=nullif(p_dados->>'chave',''); BEGIN
 IF e IS NULL OR u IS NULL OR NOT public.is_usuario_interno(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
 IF jsonb_typeof(p_itens) IS DISTINCT FROM 'array' OR jsonb_array_length(p_itens)>500 THEN RAISE EXCEPTION 'Itens inválidos'; END IF;
 IF un IS NULL OR NOT EXISTS(SELECT 1 FROM unidades WHERE id=un AND estabelecimento_id=e) THEN RAISE EXCEPTION 'Escolha uma unidade válida'; END IF;
 IF f IS NULL OR NOT EXISTS(SELECT 1 FROM empresas WHERE id=f AND estabelecimento_id=e) THEN RAISE EXCEPTION 'Escolha um fornecedor válido'; END IF;
 IF chave IS NOT NULL THEN IF chave !~ '^[0-9]{44}$' THEN RAISE EXCEPTION 'Chave inválida'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(e::text||chave,0)); IF EXISTS(SELECT 1 FROM notas_fiscais WHERE estabelecimento_id=e AND tipo='entrada' AND notas_fiscais.chave=fiscal_salvar_entrada.chave AND (n IS NULL OR id<>n)) THEN RAISE EXCEPTION 'Esta NF-e já foi importada'; END IF; END IF;
 IF n IS NOT NULL THEN PERFORM 1 FROM notas_fiscais WHERE id=n AND estabelecimento_id=e AND tipo='entrada' AND status='rascunho' FOR UPDATE; IF NOT FOUND OR EXISTS(SELECT 1 FROM estoque_movimentos WHERE nota_fiscal_id=n) THEN RAISE EXCEPTION 'Entrada não disponível para edição'; END IF; ELSE INSERT INTO notas_fiscais(estabelecimento_id,tipo,status,origem,usuario_id) VALUES(e,'entrada','rascunho',CASE WHEN chave IS NULL THEN 'manual' ELSE 'xml' END,u) RETURNING id INTO n; END IF;
 DELETE FROM notas_fiscais_itens WHERE nota_id=n;
 FOR i IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
 IF nullif(i->>'produto_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM produtos WHERE id=(i->>'produto_id')::uuid AND estabelecimento_id=e) THEN RAISE EXCEPTION 'Produto de outra empresa'; END IF;
 IF coalesce((i->>'quantidade')::numeric,0)<=0 OR coalesce((i->>'fator_conversao')::numeric,0)<=0 OR coalesce((i->>'valor_unitario')::numeric,-1)<0 THEN RAISE EXCEPTION 'Quantidade, conversão ou valor inválido'; END IF;
 INSERT INTO notas_fiscais_itens(nota_id,estabelecimento_id,produto_id,codigo_origem,descricao,ncm,cfop,cst,unidade,quantidade,fator_conversao,valor_unitario,valor_total,aliq_icms,valor_icms,aliq_ipi,valor_ipi,aliq_pis,valor_pis,aliq_cofins,valor_cofins,quantidade_recebida) VALUES(n,e,nullif(i->>'produto_id','')::uuid,i->>'codigo_origem',coalesce(i->>'descricao',''),i->>'ncm',i->>'cfop',i->>'cst',i->>'unidade',(i->>'quantidade')::numeric,(i->>'fator_conversao')::numeric,(i->>'valor_unitario')::numeric,(i->>'valor_total')::numeric,coalesce((i->>'aliq_icms')::numeric,0),coalesce((i->>'valor_icms')::numeric,0),coalesce((i->>'aliq_ipi')::numeric,0),coalesce((i->>'valor_ipi')::numeric,0),coalesce((i->>'aliq_pis')::numeric,0),coalesce((i->>'valor_pis')::numeric,0),coalesce((i->>'aliq_cofins')::numeric,0),coalesce((i->>'valor_cofins')::numeric,0),(i->>'quantidade')::numeric);
 END LOOP;
 UPDATE notas_fiscais SET unidade_id=un,empresa_id=f,chave=fiscal_salvar_entrada.chave,numero=p_dados->>'numero',serie=p_dados->>'serie',data_emissao=nullif(p_dados->>'data_emissao','')::date,natureza_operacao=p_dados->>'natureza_operacao',participante_nome=p_dados->>'participante_nome',participante_cnpj=p_dados->>'participante_cnpj',participante_uf=p_dados->>'participante_uf',xml=p_dados->>'xml',valor_produtos=coalesce((p_dados->>'valor_produtos')::numeric,0),valor_frete=coalesce((p_dados->>'valor_frete')::numeric,0),valor_desconto=coalesce((p_dados->>'valor_desconto')::numeric,0),valor_icms=coalesce((p_dados->>'valor_icms')::numeric,0),valor_icms_st=coalesce((p_dados->>'valor_icms_st')::numeric,0),valor_ipi=coalesce((p_dados->>'valor_ipi')::numeric,0),valor_pis=coalesce((p_dados->>'valor_pis')::numeric,0),valor_cofins=coalesce((p_dados->>'valor_cofins')::numeric,0),valor_total=coalesce((p_dados->>'valor_total')::numeric,0),dados_emissao=coalesce(p_dados->'dados_emissao','{}'::jsonb),observacoes=p_dados->>'observacoes',updated_at=now() WHERE id=n;
 INSERT INTO nfe_entrada_conferencia(estabelecimento_id,nota_id,situacao,usuario_id) VALUES(e,n,'pendente',u) ON CONFLICT(nota_id) DO UPDATE SET situacao='pendente',updated_at=now(); RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.fiscal_salvar_entrada(uuid,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fiscal_salvar_entrada(uuid,jsonb,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.fiscal_preservar_dados_rascunho() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.tipo='saida' AND NEW.motor_emissao='proprio' AND NEW.status='rascunho' THEN
 IF NEW.tipo_operacao_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fiscal_tipos_operacao WHERE id=NEW.tipo_operacao_id AND estabelecimento_id=NEW.estabelecimento_id) THEN RAISE EXCEPTION 'Tipo de operação de outra empresa'; END IF;
 SELECT jsonb_set(NEW.dados_emissao,'{itens}',coalesce(jsonb_agg(jsonb_build_object('produto_id',i.produto_id,'descricao',i.descricao,'codigo',i.codigo_origem,'ncm',i.ncm,'unidade',i.unidade,'quantidade',i.quantidade,'valor_unitario',i.valor_unitario,'desconto',coalesce((NEW.dados_emissao#>>ARRAY['itens',((rownum-1)::text),'desconto'])::numeric,0),'frete',coalesce((NEW.dados_emissao#>>ARRAY['itens',((rownum-1)::text),'frete'])::numeric,0),'seguro',coalesce((NEW.dados_emissao#>>ARRAY['itens',((rownum-1)::text),'seguro'])::numeric,0),'outras',coalesce((NEW.dados_emissao#>>ARRAY['itens',((rownum-1)::text),'outras'])::numeric,0),'tributacao',i.tributacao)),'[]'::jsonb)) INTO NEW.dados_emissao FROM (SELECT t.*,row_number() OVER(ORDER BY created_at,id) AS rownum FROM notas_fiscais_itens t WHERE nota_id=NEW.id) i;
 END IF; RETURN NEW; END $$;
COMMENT ON FUNCTION public.fiscal_preservar_dados_rascunho() IS 'Reserved helper; full draft items are persisted through fiscal_rascunho_completo instead.';
CREATE OR REPLACE FUNCTION public.fiscal_rascunho_completo(p_nota uuid,p_chave text,p_dados jsonb,p_itens jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; i jsonb; BEGIN
 FOR i IN SELECT value FROM jsonb_array_elements(p_itens) LOOP IF coalesce((i->>'quantidade')::numeric,0)<=0 OR coalesce((i->>'valor_unitario')::numeric,-1)<0 OR coalesce((i->>'desconto')::numeric,0)<0 OR coalesce((i->>'frete')::numeric,0)<0 OR coalesce((i->>'seguro')::numeric,0)<0 OR coalesce((i->>'outras')::numeric,0)<0 OR coalesce((i->>'desconto')::numeric,0)>(i->>'quantidade')::numeric*(i->>'valor_unitario')::numeric THEN RAISE EXCEPTION 'Quantidade, preço ou despesas inválidas'; END IF; END LOOP;
 IF nullif(p_dados->>'tipo_operacao_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fiscal_tipos_operacao WHERE id=(p_dados->>'tipo_operacao_id')::uuid AND estabelecimento_id=public.get_auth_user_estabelecimento_id()) THEN RAISE EXCEPTION 'Tipo de operação de outra empresa'; END IF;
 n:=public.fiscal_salvar_rascunho(p_nota,p_chave,p_dados,p_itens); UPDATE notas_fiscais SET dados_emissao=jsonb_set(p_dados,'{itens}',p_itens),orcamento_id=CASE WHEN p_chave LIKE 'pedido:%' THEN substring(p_chave FROM 8)::uuid ELSE orcamento_id END WHERE id=n; RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.fiscal_rascunho_completo(uuid,text,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fiscal_rascunho_completo(uuid,text,jsonb,jsonb) TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.nfe_eventos,public.nfe_transmissoes FROM authenticated;
CREATE OR REPLACE FUNCTION public.fiscal_apos_entrada() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.tipo='entrada' AND NEW.status='lancada' AND OLD.status IS DISTINCT FROM 'lancada' THEN PERFORM public.fiscal_integrar_titulos(NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER fiscal_titulos_entrada AFTER UPDATE OF status ON public.notas_fiscais FOR EACH ROW EXECUTE FUNCTION public.fiscal_apos_entrada();